import{_ as l,l as i,o as e,c as n,v as r,p as s,x as t,d,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"梯度消失与爆炸","description":"","frontmatter":{"title":"梯度消失与爆炸","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vanish-explode-grad.md","filePath":"llm/vanish-explode-grad.md","lastUpdated":1789023840000}'),m={name:"llm/vanish-explode-grad.md"};function p(B,a,c,A,_,u){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="梯度消失与爆炸" tabindex="-1">梯度消失与爆炸 <a class="header-anchor" href="#梯度消失与爆炸" aria-label="Permalink to &quot;梯度消失与爆炸&quot;">​</a></h1><div class="epigraph"><p>反向路径是一串局部增益的乘积；每层略小于 $1$ 则深层梯度消失，每层略大于 $1$ 则爆炸。</p><footer>—— 据 Hochreiter, Untersuchungen zu dynamischen neuronalen Netzen, 1991；Bengio, Simard &amp; Frasconi, IEEE Trans. Neural Networks, 1994；Pascanu, Mikolov &amp; Bengio, ICML 2013 整理</footer></div><p><a href="/llm/autograd-two-modes">自动微分的正向与反向模式</a>说明训练走反向。本课不比较 AD 模式。缺口是：反向即使实现正确，深层参数仍可能收到接近 \\(0\\) 或 Inf 的梯度。原因是局部 Jacobian 的奇异值沿深度连乘。本课把这一乘法结构钉住；残差、合适的初始化、非饱和激活、门控，是后面若干课分别补的洞，这里不提前讲完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一层的反向把 \\(\\mathrm{d}h^{(\\ell+1)}\\) 乘上 \\(W^\\top\\odot\\sigma&#39;\\) 一类增益，得到 \\(\\mathrm{d}h^{(\\ell)}\\)。\\(L\\) 层之后，最浅层看到的是 \\(L\\) 个矩阵的乘积作用在 \\(\\mathrm{d}h^{(L)}\\) 上。若这些矩阵的典型增益 \\(\\rho\\lt 1\\)，则 \\(\\rho^L\\to 0\\)；若 \\(\\rho\\gt 1\\)，则 \\(\\rho^L\\to\\infty\\)。缺口不是链式法则写错，而是深度把「每层一点点」放大成指数。浅层参数几乎收不到有效更新，或一步就被打飞——两者都会让深层网络训不动。</p><p>循环网络沿时间展开后，深度等于序列长度，问题更尖锐：那是<a href="/llm/rnn-long-range">RNN 与长程依赖</a>的缺口。本课先在前馈深度上把同一乘法说清，避免后课把 LSTM 当成全新魔法。</p><h3 id="梯度裁剪不是「消失的对称解」" tabindex="-1">梯度裁剪不是「消失的对称解」 <a class="header-anchor" href="#梯度裁剪不是「消失的对称解」" aria-label="Permalink to &quot;梯度裁剪不是「消失的对称解」&quot;">​</a></h3><p>爆炸时，\\(\\|\\nabla L\\|\\) 超过阈值就缩放，能让一步更新有限。消失时，梯度已经是 \\(0\\)，裁剪不改变 \\(0\\)。两者不是同一旋钮的两端。裁剪是爆炸的工程闸门，对消失无效。消失要改增益结构：激活不要把导数长期压在 \\(0\\) 附近、初始化不要让 \\(\\|W\\|\\) 过小、深度路径上要有增益接近 \\(1\\) 的旁路。后课残差专门提供这条旁路。</p><p><span class="marginnote">诊断应分层看梯度范数，不要只看全局 \\(\\|\\nabla L\\|\\)。全局范数可能被某一层的爆炸主导，而另一层已经消失。日志里按层打印 \\(\\mathrm{d}W\\) 的 RMS，比只打印损失更早暴露。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>粗诊断：记录各层 \\(\\mathrm{d}h\\) 与 \\(\\mathrm{d}W\\) 的 RMS 随深度的变化。单调掉到数值噪声：消失；随深度指数上升或频繁 Inf：爆炸。饱和激活（sigmoid、tanh 在幅值大时 \\(\\sigma&#39;\\approx 0\\)）提供 \\(\\lt 1\\) 的逐元素增益；随机初始化若 \\(\\|W\\|_2\\) 期望偏离 \\(1\\)，提供矩阵增益。两者相乘。梯度裁剪：若 \\(\\|g\\|\\gt c\\)，令 \\(g\\leftarrow g\\cdot c/\\|g\\|\\)，再交给优化器。它改变步长，不改变方向（在欧氏范数下）。</p>',11)),(e(),s(E,null,{default:t(()=>[h(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOP%5B%22%E9%A1%B6%E5%B1%82%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20MUL%5B%22%E4%B9%98%E6%9C%AC%E5%B1%82%20W%20%E8%BD%AC%E7%BD%AE%E4%B8%8E%E6%BF%80%E6%B4%BB%E5%AF%BC%E6%95%B0%22%5D%0A%20%20MUL%20--%3E%20NEXT%5B%22%E6%9B%B4%E6%B5%85%E4%B8%80%E5%B1%82%22%5D%0A%20%20NEXT%20--%3E%20PROD%5B%22%E6%B7%B1%E5%BA%A6%E4%B8%AA%E5%A2%9E%E7%9B%8A%E8%BF%9E%E4%B9%98%22%5D%0A%20%20PROD%20--%3E%7C%22%E5%B0%8F%E4%BA%8E%201%20%E7%9A%84%20L%20%E6%AC%A1%E6%96%B9%22%7C%20VAN%5B%22%E6%B6%88%E5%A4%B1%22%5D%0A%20%20PROD%20--%3E%7C%22%E5%A4%A7%E4%BA%8E%201%20%E7%9A%84%20L%20%E6%AC%A1%E6%96%B9%22%7C%20EXP%5B%22%E7%88%86%E7%82%B8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>反向是线性化。每层在当前点的一阶近似是一个矩阵；深度复合的一阶近似是矩阵乘积。乘积的谱半径偏离 \\(1\\) 时，只有指数可以描述深度效应。这与前向信号的消失 / 爆炸是对偶现象：前向 \\(\\|h\\|\\) 崩掉时，反向往往一并崩掉，因为 \\(\\sigma&#39;\\) 与 \\(W\\) 是同一组量。初始化课将管前向方差；残差课将管「至少有一条增益为 \\(1\\) 的路径」；LSTM 将管时间轴上的增益。本课只提供共同语言：看连乘，不要只看某一层。</p><p>softmax 饱和也是一种局部增益接近 \\(0\\)（见交叉熵课的 \\(p-y\\) 在 \\(p\\) 极尖时）。它发生在最后一层，会让整个反向变弱，但不随深度指数恶化。深度连乘与末层饱和要分开诊断。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 BatchNorm / LayerNorm 的公式，不写残差 \\(h+f(h)\\)。下一课起进入前馈网络，从<a href="/llm/linear-layer-bias">线性层与偏置</a>把仿射补全。后课默认：深层训不动时，先分层看梯度范数，再决定是裁剪、改激活、改初始化还是加旁路。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>反向是局部增益连乘；\\(\\rho^L\\) 在深度上指数地消失或爆炸。</li><li>裁剪只对付爆炸，不对付消失。</li><li>饱和激活与 \\(\\|W\\|\\) 偏离 \\(1\\) 是两类增益来源，诊断要按层。</li><li>循环展开把深度换成时间，同一乘法稍后会再出现。</li><li>出处：Hochreiter, 1991；Bengio et al., 1994；Pascanu et al., ICML 2013。</li></ul>',7))])}const T=l(m,[["render",p]]);export{g as __pageData,T as default};
